/* c(): compact course builder. opts: kind, stream, alternatives, phase, note, activities, resources */
function nc(id, title, semester, category, credits, opts = {}) {
  return Object.assign({
    id, title, semester, academicYear: Math.ceil(semester / 2), category, credits,
    kind: 'graded', electiveStream: null, alternatives: null, phase: null, note: null,
    activities: null, resources: []
  }, opts);
}

